INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-151-tell-us-internal-admin-user-business', 56, '2026-08-06'::date, 'Admin', 'Tell-Us internal administration management tooling and password reset', 'Introduces full internal management tooling for Tell-Us admin users covering account management, brand plans and owners, moderation queues, economy configuration, transaction audit logging, and a public password reset flow.', '["New internal admin surface under `/tellus/admin/*` for account, brand, moderation, and economy management.", "Account controls: list/search users, view details, suspend/unsuspend, force sign-out, verify emails, generate password-reset links, and manually adjust points balance.", "Brand controls: list/search brands, comp or cancel subscription plans, and assign brand owners.", "Moderation controls: cross-brand review queue and DM thread oversight (view, block, unblock).", "Economy controls: editors for earning rules, badge definitions, and listing configs.", "Audit trail: full transaction-bound mutation logging in `tellus_admin_audit` viewable from the admin interface.", "Password reset flow: public `/auth/reset-password` endpoint and reset page."]'::jsonb, '["Internal Admin: Access `/tellus/admin/*` pages via the grouped ''Internal'' navigation section in Tell-Us.", "Password Reset: Access `/auth/reset-password` via email reset links."]'::jsonb, '["Apply migration `tellus_app_08_admin_management.py` (`tellus_app_08`).", "Set `TELLUS_ADMIN_EMAILS` in `.env.backend`."]'::jsonb, NULL, 'action-needed', '2026-08-08T22:26:15.032229+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-154-tell-us-fan-board-brand-posts-moderated', 54, '2026-08-07'::date, 'Marketing', 'Tell-Us Fan Board for brand posts, moderated replies, and board rewards', 'Introduces Fan Boards for Tell-Us, allowing brands to post deals, news, and events to approved fans, moderate fan replies before publishing, and offer board-exclusive reward listings.', '["Fan Boards: Brands can share posts with approved fan members and assign team moderators.", "Moderated replies: Fan replies default to held status until approved by brand moderators, awarding loyalty points upon approval.", "Board-exclusive rewards: Brands can feature exclusive reward listings redeemable directly from the feed.", "Admin moderation queues: Cross-brand post and reply moderation tools under /admin/board-*."]'::jsonb, '["Consumers: Request to join via the public brand page, view posts, and reply in Boards.", "Brands: Post content, approve fan join requests with loyalty signals, and moderate replies in Brand > Board.", "Admins: Review cross-brand post and reply queues under Admin > Moderation."]'::jsonb, '["Apply migration tellus_app_12_regulars_board."]'::jsonb, NULL, 'action-needed', '2026-08-08T22:26:15.048069+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-153-tell-us-reward-expiry-redemption', 53, '2026-08-07'::date, 'Marketing', 'Tell-Us reward expiry, redemption context, rolling reviews, logo upload, and store addresses', 'Updates to Tell-Us features including configurable reward expiration, brand and location context on redemption views, rolling 12-month public review scores, image uploads for brand logos, and store address displays.', '["Reward expiry: Brand-configurable expiration (default 30 days) stamped at redemption, preventing expired codes from being claimed.", "Redemption context: Added brand name, city, and state details to ''My rewards'' and brand redemption lists.", "Rolling reviews: Public ratings and search counts now reflect a rolling 12-month window, with older published reviews available under a toggle.", "Logo upload: Replaced raw text logo URL field with direct S3 multipart image upload (PNG/JPEG/WebP, max 2MB).", "Store address: Displayed the primary store address, city, and state on public brand pages (/b/{slug})."]'::jsonb, '["Brands: Upload logo under Settings; configure expiry days per listing under Listings.", "Consumers: View brand location and state details under My Rewards and public brand pages."]'::jsonb, '["Apply migration tellus_app_11_listing_expiry \u2014 not yet applied to dev/prod."]'::jsonb, NULL, 'action-needed', '2026-08-08T22:26:15.046927+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-152-tell-us-reviews-on-unclaimed-businesses', 52, '2026-08-07'::date, 'Admin', 'Unclaimed business reviews and Google Places autocomplete', 'Unclaimed businesses now automatically maintain active intake links so consumers can leave reviews, while the add-a-place flow gains server-proxied Google Places autocomplete and place deduplication.', '["Reviews on unclaimed businesses: Unclaimed brands now automatically generate and maintain active intake links so public feedback is never blocked.", "Google Places autocomplete: Added debounced address autocomplete on the add-a-place form, securely proxied through the server.", "Place deduplication: Submissions now deduplicate using google_place_id with server-side validation of location details.", "Navigation: Added a Places navigation link for signed-in consumers."]'::jsonb, '["Consumers: Go to Places in the navigation bar to search or add places using autocomplete.", "Admin: Unassigning a brand owner automatically guarantees an active community review link."]'::jsonb, '["Apply migration tellus_app_09 (adds google_place_id index).", "Set GOOGLE_MAPS_API_KEY environment variable to enable server-side Google Places autocomplete."]'::jsonb, NULL, 'action-needed', '2026-08-08T22:26:15.044893+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-159-gummfit-ios-phase-1-2-sites-switcher', 51, '2026-08-08'::date, 'Cappe', 'iOS Site Switcher, Home Readiness Checklist, and Site Publishing', 'Adds site management features to the iOS app, including site creation, active site switching, a Home tab readiness checklist with publish actions, and discoverability controls.', '["Site tracking and switcher: Persists the active site and provides a site creation flow.", "Home tab readiness checklist: View readiness status and publish sites, with error details displayed if publishing is blocked.", "Discover listing sheet: Toggle discoverability status for listed sites."]'::jsonb, '["iOS App: Manage and switch sites, complete readiness checklist items on the Home tab, and publish sites directly within the app."]'::jsonb, NULL, NULL, 'new', '2026-08-08T22:26:15.055757+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-158-gummfit-ios-app-phase-0-scaffold', 50, '2026-08-08'::date, 'Cappe', 'Gummfit iOS app initial scaffolding (Phase 0)', 'Initial project scaffolding for the Gummfit iOS app, including authentication service integration, session restoration, and core login and signup flows.', '["Initial iOS app project setup using XcodeGen.", "Integrated Cappe authentication service supporting login, signup, and keychain session restoration.", "Added core authentication screens for Login, Signup (business, personal, and creator account types), and Verification Wait."]'::jsonb, '["Open and build the Gummfit iOS project in Xcode (iOS 17+ target)."]'::jsonb, NULL, NULL, 'new', '2026-08-08T22:26:15.053884+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-157-tell-us-google-sign-in-with-auto', 49, '2026-08-08'::date, 'Matcha Work', 'Fix Google ID token audience validation in Matcha core', 'Fixed a security bug in Matcha core''s Google sign-in endpoint where ID tokens were verified without audience restrictions.', '["Fixed: `/api/auth/google` now verifies Google ID tokens against an audience allowlist, rejecting tokens minted for unauthorized OAuth clients."]'::jsonb, '[]'::jsonb, '["Ensure Google OAuth Client ID audience configuration is set in server environment variables."]'::jsonb, NULL, 'action-needed', '2026-08-08T22:26:15.052099+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-156-beetlejuse-ios-glassmorphic-dark-amber', 48, '2026-08-08'::date, 'Matcha Work', 'Black and amber redesign and Beetlejuse app rename for iOS', 'Redesigned the iOS app with a flat black and amber design system, updated all user-facing app branding to Beetlejuse, and fixed a layout bug on the login screen.', '["Updated authentication and consumer home screens with a new black/amber design system.", "Renamed user-facing app copy, display name, and permission descriptions to Beetlejuse.", "Fixed: resolved an EmberBackground background scaling issue that pushed LoginView content off-screen."]'::jsonb, '["Launch the iOS app to see the updated Beetlejuse wordmark and black/amber theme across authentication and home views."]'::jsonb, NULL, NULL, 'new', '2026-08-08T22:26:15.050785+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-160-feat-gummfit-ios-phase-3-4-5-catalog', 47, '2026-08-08'::date, 'Cappe', 'iOS App Phase 3-5: Catalog, Sales, and CRM/Venue management', 'Adds broad iOS admin capabilities spanning product catalog management, inventory tracking, order and booking sales workflows, customer messaging, client lists, reviews, and venue management.', '["Catalog: Create and edit products with options and photo attachments, track stock levels, log inventory adjustments, and set up discounts.", "Sales & Bookings: Process orders with tracking and receipt PDFs, configure booking types, set availability and rate rules, and action pending requests from a unified queue on Home.", "CRM & Venue: Handle inbox threads with public link support, manage client profiles, monitor reviews, and configure venue locations and staff.", "Fixed: Photos picked as HEIC are now uploaded with their native format content type instead of being mislabeled as image/jpeg.", "Fixed: Saving availability and rate rules on multi-location sites no longer duplicates location-scoped rows as shared rows.", "Fixed: Product updates no longer send fulfillment data unless intended, avoiding plan-entitlement gating errors."]'::jsonb, '["Catalog: Owner navigation -> Catalog tab for products, inventory adjustment, and discounts.", "Sales: Owner navigation -> Sales tab for orders, booking setup, availability, and rate rules.", "CRM & Venue: Owner navigation -> Inbox tab for customer conversations, or More tab for clients, reviews, and locations/staff."]'::jsonb, NULL, NULL, 'new', '2026-08-11T21:58:16.675230+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-155-feat-tellus-add-native-ios-app', 46, '2026-08-08'::date, 'Analysis Pilot', 'Native iOS app for TellUs (Consumer & Brand)', 'Introduces a native iOS application built with SwiftUI, bringing web feature parity for both consumer and brand accounts into a single binary with role switching at login.', '["New native iOS app supporting both consumer and brand account roles.", "Full feature parity with web for auth, rewards marketplace and redeeming, boards and discussions, direct messaging, brand stores, and brand settings.", "Support for QR/link intake with streaming photo and video uploads.", "60-second polling notifications matching web client behavior.", "Fixed: resolved issue where intake forms were permanently unsubmittable for claimed brands.", "Fixed: resolved 401 auth handling and scanner re-arm bugs."]'::jsonb, '["Open the TellUs app on iOS and sign in using consumer or brand credentials."]'::jsonb, NULL, '["Stripe checkout, Google Places search, the admin console, and self-serve password reset requests remain web-only in v1."]'::jsonb, 'new', '2026-08-08T22:26:15.049099+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-164-tell-us-flyer-design-assistant-ios', 45, '2026-08-09'::date, 'Marketing', 'AI flyer design assistant and iOS promo surface', 'Adds an AI design assistant to the promo flyer designer with semantic palette tokens for automated restyling, alongside the new iOS promo surface for browsing, scanning, and claiming promotional cards.', '["AI design assistant in the campaign designer to generate layouts and update flyer properties via natural language.", "Semantic palette tokens (ink, paper, brand, accent, muted) allowing full-flyer color theme swaps.", "iOS promo surface allowing users to browse promos, scan campaign QR codes, and claim cards."]'::jsonb, '["Web: Brand -> Campaign Designer to access the AI design assistant panel and palette controls.", "iOS: Open the TellUs app to scan QR codes and view/claim active promo cards."]'::jsonb, NULL, NULL, 'new', '2026-08-11T21:58:16.684791+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-163-tellus-promo-campaigns-backend-brand', 44, '2026-08-09'::date, 'Marketing', 'Promo campaigns and scanner device management for Tellus', 'Introduces backend services and brand management UI for Tellus promo campaigns, allowing brands to launch QR reward card campaigns with claim caps and issue per-store scanner links for counter redemptions.', '["Brand campaign management: Create, pause, resume, and cancel promo campaigns from the Campaigns interface.", "QR and scanner device links: Mint and revoke per-store scanner links for staff to process redemptions without requiring account logins.", "Atomic claim and redemption logic to handle campaign claim limits safely."]'::jsonb, '["Brand users: Navigate to the Campaigns page in Tellus to set up new promo campaigns, retrieve QR/claim links, or issue store scanner links."]'::jsonb, '["Apply migration tellus_app_16 \u2014 not applied to any database as of this commit."]'::jsonb, NULL, 'action-needed', '2026-08-11T21:58:16.683889+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-162-integrate-oceanlab-music-catalog-into', 43, '2026-08-09'::date, 'Matcha Work', 'Integrate Oceanlab music catalog into monorepo', 'Integrates the Oceanlab music catalog and label ingestion pipeline into the main codebase, adding API routes under /api/oceanlab, a dedicated Vite web client at /oceanlab/, and 20 oceanlab_* database tables.', '["New Oceanlab backend service mounted at /api/oceanlab for music catalog and label ingestion management.", "New Oceanlab web app available at /oceanlab/.", "Bearer token authentication introduced for Oceanlab API endpoints."]'::jsonb, '["Navigate to /oceanlab/ in the web client to manage catalog items.", "Use the OCEANLAB_TOKEN bearer token when making requests to /api/oceanlab endpoints."]'::jsonb, '["Apply migration server/alembic/versions/oceanlab_app_01_standalone.py to create the oceanlab_* tables.", "Set the OCEANLAB_TOKEN environment variable in server environments."]'::jsonb, NULL, 'action-needed', '2026-08-11T21:58:16.682743+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-175-fix-espresso-desktop-workspace-creation', 42, '2026-08-10'::date, 'Matcha Work', 'Fix workspace creation, plan-gate messaging, and channel sorting', 'Fixes workspace creation build issues, surfaces actionable plan-gate error messaging, labels Pro-only workspace types, updates Matcha Work branding, and resolves a channel-star sorting error.', '["Labeled Pro-only workspace types and updated visible Matcha Work branding.", "Surfaced actionable messaging when plan-gate errors occur during workspace creation.", "Fixed: channel-star sorting actor-isolation error.", "Fixed: renamed entitlements path issue causing desktop target build failures."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-11T21:58:16.686921+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-173-feat-huume-add-draft-pr-agent', 41, '2026-08-10'::date, 'Matcha Work', 'Huume code agent and draft PR guardrails', 'Introduces the feature-gated Huume code agent and worker in Matcha Work, supporting automated draft PR creation with fail-closed GitHub write helpers, guardrails, and run auditing.', '["New feature-gated Huume code agent and background worker for code task execution.", "Fail-closed GitHub write helpers and draft PR guardrails.", "Run and step auditing with stale-run recovery."]'::jsonb, '[]'::jsonb, '["Apply migration huumecode01."]'::jsonb, NULL, 'action-needed', '2026-08-11T21:58:16.686186+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-166-harden-cappe-routes-and-add', 40, '2026-08-10'::date, 'Cappe', 'Harden CAPPE routes and add collab/domain reconciliation workers', 'Hardened CAPPE routes against race conditions on financial operations, enhanced validation across uploads, inventory, and bookings, and added automated background workers for collab and domain reconciliation.', '["Fixed: money-path race conditions and stale unmatched webhook claims in CAPPE routes.", "Enhanced route validation for file upload bytes, nullable PATCH parameters, booking overlaps, and inventory history.", "Added background reconciliation workers for collaboration auto-approval and domain finalization."]'::jsonb, '[]'::jsonb, '["Apply migration zzzzcappe30_cappe_worker_schedulers \u2014 not applied as of this commit."]'::jsonb, NULL, 'action-needed', '2026-08-11T21:58:16.685470+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-179-docs-add-matcha-work-implementation-plan', 39, '2026-08-11'::date, 'Matcha Work', 'Matcha Work messaging terminology, permissions, and event actions', 'Introduces workspace and channel permission management, event draft confirmations, and action surfacing within Matcha Work.', '["Added role-based permission controls and audit tracking for Matcha Work workspaces and channels.", "Added support for event draft confirmation and surfacing channel actions directly in chat.", "Updated messaging terminology and permissions models across client and backend APIs."]'::jsonb, '["Matcha Work: Access permissions and channel actions via channel settings and action drawers."]'::jsonb, '["Apply migrations ems03_work_event_actions, mwperm01_work_permissions, and mwperm02_work_permission_audit."]'::jsonb, NULL, 'action-needed', '2026-08-13T00:50:14.036867+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-176-fix-tellus-board-likes-replies-and-ios', 38, '2026-08-11'::date, 'Admin', 'Board post likes, brand replies, and iOS validation error handling', 'Board moderators and owners can now like accessible non-visible posts and access the web reply composer. Brand team members can post auto-approved replies, and the iOS app now cleanly formats API validation errors.', '["Board moderators and owners can now like non-visible posts they have permission to access.", "Brand team members and owners can submit auto-approved replies to board posts.", "Web: board reply composer is now visible to moderators and owners.", "Fixed: iOS client now parses FastAPI validation error arrays into readable text instead of raw JSON."]'::jsonb, '["Web: open a board post while logged in as a moderator or owner to view and use the reply composer."]'::jsonb, NULL, NULL, NULL, '2026-08-11T21:58:16.687907+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-188-feat-gummfit-ios-redesign-operator-login', 37, '2026-08-12'::date, 'Cappe', 'Booking calendar and staff availability updates', 'Updates to the Cappe site booking interface, including revised schedule and staff availability sections alongside improved availability logic.', '["Updated the Bookings page with improved schedule and staff availability sections.", "Refined booking availability logic and calendar display for site bookings."]'::jsonb, '["Navigate to Cappe -> Site -> Bookings to manage schedule and staff availability."]'::jsonb, NULL, NULL, 'new', '2026-08-13T00:50:14.055502+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-187-feat-work-add-workspace-access-manager', 36, '2026-08-12'::date, 'Matcha Work', 'Workspace access manager and guided permission setup', 'Introduces a Workspace Access Manager under People with effective default and custom grant visibility, a guided access-level wizard, and expanded effective access resolution across user roles.', '["New Workspace Access Manager in People with default and custom grant visibility.", "Guided permission wizard explaining Member, Reviewer, Operator, and Admin authority levels.", "Expanded permission API returning effective access for employees, clients, collaborators, owners, and explicit grants."]'::jsonb, '["Navigate to People > Workspace Access to manage permissions and view access-level guidance."]'::jsonb, NULL, NULL, 'new', '2026-08-13T00:50:14.054478+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-186-fix-huume-bound-schedule-retry-loops', 35, '2026-08-12'::date, 'Employee Scheduling', 'Bound Huume schedule retry loops and prevent duplicate proposals', 'Updated Huume''s scheduling agent and skill logic to prevent repeated duplicate schedule proposals within a single turn, handle terminal clarifications/refusals, and cap retry prompt-token consumption.', '["Fixed: duplicate and repeated schedule proposals within a single Huume turn are now blocked while preserving confirmation turns.", "Added terminal clarification and refusal handling for schedule proposals to prevent indefinite retry loops.", "Added a 100k cumulative prompt-token bound and retry/stop telemetry for Huume scheduling interactions."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-13T00:50:14.053619+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-185-fix-merlin-bound-repeated-tool-retries', 34, '2026-08-12'::date, 'Cappe', 'Prevent infinite tool retry loops and bound tokens in Merlin', 'Updated Merlin''s loop control with batch-aware no-progress detection to stop repeated rejected actions, refusals, and tool failures without discarding successful work. Also introduced per-turn token ceilings and image attachment pruning after planning.', '["Fixed: Merlin tool loops now halt on repeated rejected actions, refusals, or tool failures while preserving successful sibling execution results.", "Added per-turn token ceilings and image pruning for attachment assets post-planning."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-13T00:50:14.052526+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-184-fix-cappe-separate-creator-onboarding', 33, '2026-08-12'::date, 'Cappe', 'Fix creator onboarding routing and cap Merlin agent retries', 'Updates onboarding routing so creator accounts land on their creator profile dashboard, and bounds Merlin setup and page-editor retry loops to prevent runaway calls.', '["Fixed: Gummfit Creator accounts on the shared business onboarding route are now sent to their creator profile dashboard.", "Fixed: Merlin setup and page-editor loops now cap repeated rejected calls while preserving one correction attempt."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-13T00:50:14.051693+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-182-fix-huume-offer-letter-preview-refresh', 32, '2026-08-12'::date, 'Matcha Work', 'Fix Huume offer letter preview refresh and support reporting_to field', 'Huume offer letter previews now refresh automatically when thread versions update, preventing race conditions from stale requests. Additionally, the reporting_to field is now editable via Huume and persists to the offer letter manager field.', '["Fixed: offer letter previews in Huume now update correctly on thread version changes and ignore stale concurrent preview responses.", "The ''reporting_to'' manager field can now be edited via Huume and persists to offer letter drafts."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-13T00:50:14.050747+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-181-fix-repair-gummfit-setup-and-preview', 31, '2026-08-12'::date, 'Cappe', 'Fix Cappe setup shortcuts and editor site previews', 'Fixes setup guide shortcuts in Cappe, including the logo upload action, and addresses preview rendering issues for store and booking widgets in the site editor.', '["Fixed: setup guide shortcuts, including the ''Add your logo'' action, now trigger correctly.", "Fixed: published-site editor previews now accurately render store and booking widgets."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-13T00:50:14.049519+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-180-feat-assign-events-to-work-channels', 30, '2026-08-12'::date, 'Matcha Work', 'Assign events to work channels', 'Enables assigning events directly to work channels, featuring channel action cards, permissions, notifications, and event status lifecycle management.', '["Assign events to work channels directly from event details or the channel actions drawer.", "Channel action cards and notifications for event assignment, completion, and cancellation.", "Updated work permissions governing event assignment management."]'::jsonb, '["Open an Event Detail or Channel View -> Actions Drawer to assign an event to a work channel."]'::jsonb, '["Apply migration ems04_event_assignments."]'::jsonb, NULL, 'action-needed', '2026-08-13T00:50:14.048289+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-190-fix-cappe-prevent-booking-slot-server', 29, '2026-08-13'::date, 'Cappe', 'Prevent server error during booking slot checks', 'Fixes a server error caused by PostgreSQL range expression type mismatch when evaluating booking slot overlaps.', '["Fixed: resolved a server error during booking slot availability checks by explicitly casting overlap range bounds."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-14T09:18:13.680417+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-189-fix-tellus-avoid-mobile-flyer-fetch', 28, '2026-08-13'::date, 'Marketing', 'Fix campaign flyer export failure on mobile WebKit', 'Fixed an issue where exporting a campaign flyer on mobile Safari and WebKit browsers failed with a generic fetch error before the flyer payload reached the backend.', '["Fixed: campaign flyer export on mobile browsers now uses Konva native blob conversion to avoid image fetch failures."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-13T00:50:14.056493+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-194-feat-ops-separate-matcha-work-and', 27, '2026-08-14'::date, 'Ops', 'Separate Matcha Work and Matcha Ops surfaces with dedicated permissions and channel scoping', 'Separates Matcha Work project discussion from Matcha Ops company channels and operational automation, introducing scoped channel access, calls policies, new /ops routing, and admin entitlement management.', '["New dedicated operational surface accessible via /ops route.", "Scoped channel access and calls policies separating project chat from operational company channels.", "Admin health and entitlement management tooling for Matcha Ops permissions."]'::jsonb, '["Access operational automation and company channels via /ops.", "Admins: Manage Matcha Ops feature entitlements under Admin -> Matcha Ops."]'::jsonb, '["Apply migrations matchaops01_channel_scopes and matchaops02_ops_permissions \u2014 not applied to any database as of this commit."]'::jsonb, NULL, 'action-needed', '2026-08-14T09:18:13.696566+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-193-fix-cappe-booking-timezone-display', 26, '2026-08-14'::date, 'Cappe', 'Fix Cappe booking timezone display and date grouping', 'Booking times across guest, owner, and self-service views are now displayed using the business or location timezone, ensuring calendar bookings group accurately by local date.', '["Fixed: booking times in guest, owner, and self-service views now render in the location or business local timezone.", "Fixed: calendar bookings in the owner view are now grouped by each location''s local date."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-14T09:18:13.695988+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-192-fix-ir-prevent-negative-risk-insight', 25, '2026-08-14'::date, 'IR', 'Prevent negative risk insight streaks and future-dated incident metric drift', 'Fixed issues where future-dated incidents caused negative risk insight streak values and skewed workforce compliance metrics across companies and locations.', '["Fixed: future-dated recordable incidents are now excluded from company and location workforce compliance metrics.", "Fixed: incident creation and updates now clamp future timestamps to prevent future-dated incidents.", "Fixed: legacy invalid timestamps now show no streak instead of displaying a negative elapsed-day count."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-14T09:18:13.695346+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-196-fix-ops-refresh-stale-entitlement-gates', 24, '2026-08-14'::date, 'Ops', 'Refresh entitlement gates and expose Ops navigation in Matcha-X', 'Refreshes stale `/auth/me` entitlement data across mounted client components, allows platform admins to access the Ops route, and adds Matcha Ops navigation to Matcha-X and Work sidebars.', '["Fixed: `/auth/me` entitlement data now refreshes automatically across client consumers to prevent stale access checks.", "Platform admins can now access the Ops route directly while preserving `matcha_ops` gating for tenant users.", "Exposed Matcha Ops from the Matcha-X sidebar and updated navigation between Matcha Work and Ops."]'::jsonb, '["Matcha-X: Access Matcha Ops directly from the sidebar navigation link."]'::jsonb, NULL, NULL, NULL, '2026-08-14T21:27:57.955325+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-197-feat-schedule-fold-intelligence-into', 23, '2026-08-14'::date, 'Employee Scheduling', 'Integrate Schedule Intelligence into the Schedule Editor', 'Schedule Intelligence is now consolidated into a dedicated tab within the Schedule Editor, streamlining schedule management and intelligence views into a single surface while automatically redirecting legacy routes.', '["Schedule Intelligence is now available directly as a tab inside the Schedule Editor (`/ops/schedule?tab=intelligence`).", "Standalone and legacy Intelligence URLs now automatically redirect to the unified Schedule Editor tab.", "Fixed: resolved schedule board layout overflow issues and shift-card action wrapping."]'::jsonb, '["Go to Ops -> Schedule (`/ops/schedule`) and select the Intelligence tab."]'::jsonb, NULL, NULL, NULL, '2026-08-14T21:49:17.121043+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-199-feat-schedule-surface-availability', 22, '2026-08-14'::date, 'Employee Scheduling', 'Surface forced availability overrides in Employee Scheduling', 'Forced availability overrides are now tracked across scheduling write paths and surfaced directly on shift blocks, the shift inspector, and Schedule Intelligence.', '["Shift blocks and the shift inspector now display availability override indicators when shifts are scheduled against employee constraints.", "Schedule Intelligence surfaces forced availability overrides across schedule views.", "Availability override handling is audited and standardized across shift write and assignment routes."]'::jsonb, '["Open Employee Schedule or Schedule Intelligence to inspect shifts and view flagged availability overrides."]'::jsonb, NULL, NULL, 'new', '2026-08-15T01:47:47.465486+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-191-feat-cappe-add-natural-language-booking', 21, '2026-08-14'::date, 'Cappe', 'Natural language AI booking suggestions with client verification', 'Cappe AI booking suggestions are now secured behind magic link email verification for existing clients, while manual booking remains freely available.', '["Gated AI booking suggestions behind single-use email magic links for verified existing clients.", "Manual booking remains accessible without email verification.", "Magic links expire after 15 minutes with single-use SHA-256 token hashes and 30-minute host-bound session cookies."]'::jsonb, '["Cappe Booking: Request a magic link via email to unlock AI-assisted booking suggestions."]'::jsonb, '["Apply migration cappeaiaccess01."]'::jsonb, NULL, 'action-needed', '2026-08-14T09:18:13.694208+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-202-fix-deliver-huume-offer-signature-alerts', 20, '2026-08-15'::date, 'Matcha Work', 'Deliver real-time offer signature notifications and fix EMS assignment row locking', 'Offer signature and decline notifications are now delivered immediately to the sender via real-time WebSocket updates to the Matcha Work notification bell, alongside a concurrency fix for EMS event assignments.', '["Fixed: offer signature and decline alerts now immediately notify the sender in the Matcha Work notification bell via WebSockets.", "Fixed: resolved an EMS assignment row-locking issue during event assignment updates."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-15T07:15:00.723658+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-203-fix-cappe-stop-ai-suggestion-access', 19, '2026-08-15'::date, 'Cappe', 'Fix 500 errors on AI booking suggestion access links', 'Resolves 500 errors when issuing or redeeming AI booking suggestion access links caused by a Postgres interval datatype mismatch and missing unique constraints on suggestion tables.', '["Fixed: requesting an AI booking suggestion access link no longer fails with a 500 error due to timestamp calculation mismatch.", "Fixed: re-issuing an access link for the same site and client email now cleanly updates the existing record instead of raising conflict errors."]'::jsonb, '[]'::jsonb, '["Apply migration cappesuggfix01."]'::jsonb, NULL, 'action-needed', '2026-08-15T08:15:58.760468+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-201-fix-ios-gummfit-booking-time-timezone', 18, '2026-08-15'::date, 'Cappe', 'Fix rate-limited AI booking error response', 'Nginx now returns a JSON error response with detail for 429 rate limit rejections on AI booking suggestions, preventing the widget from falling back to a generic ''Request failed'' error.', '["Fixed: the public AI-booking widget now receives a structured JSON 429 error response instead of raw HTML when rate limited, displaying the actual error message."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-15T01:47:47.472072+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-213-feat-cappe-add-merlin-ios-foundation', 17, '2026-08-17'::date, 'Cappe', 'Merlin iOS editor foundation and schema metadata', 'Introduces native iOS foundations for Cappe and Merlin, exposing editor schema metadata, theme presets, streaming APIs, and local block editing with undo/redo support.', '["Exposed complete Cappe editor schema metadata, theme configs, swatches, and font pairings for native clients.", "Added iOS foundations for pages, schema decoding, Merlin assistance, previews, and API streaming.", "Added local JSON-safe block editing on iOS with an initial Merlin operation reducer and undo/redo history support."]'::jsonb, '[]'::jsonb, NULL, NULL, 'new', '2026-08-17T06:21:51.161033+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-218-feat-schedule-gate-assignments-by', 16, '2026-08-18'::date, 'Employee Scheduling', 'Gate shift assignments by qualified schedule jobs', 'Introduces company- and location-scoped schedule jobs and qualified employee rosters, gating shift assignments and template generation so only qualified employees can be assigned unless an override is provided.', '["Company- and location-scoped schedule jobs with qualified employee roster management.", "Ability to assign jobs to shifts and recurring weekly shift templates.", "Shift assignment validation that blocks unqualified employees with a 409 conflict, allowing audited force-overrides.", "Automatic propagation of job assignments when generating weekly schedules from templates."]'::jsonb, '["Manage schedule jobs and employee qualification rosters via the schedule jobs API endpoints.", "Assign qualified jobs to individual shifts or recurring weekly templates during schedule creation."]'::jsonb, '["Apply migration empsched04_schedule_jobs."]'::jsonb, NULL, 'action-needed', '2026-08-18T07:20:30.601992+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-217-week-templates-replace-per-shift', 15, '2026-08-18'::date, 'Employee Scheduling', 'Week templates replace single-shift schedule templates', 'Shift templates are now structured as multi-block week templates rather than isolated single-shift rows. The Templates tab features a new week template builder, and the schedule assistant can now build and apply full week templates via chat.', '["Redesigned Templates tab to create and manage multi-block week templates (e.g. Standard Week) instead of standalone shift rows.", "Generate full weekly schedules under a single series directly from week templates.", "Schedule assistant support for week templates: create templates via chat or apply existing ones with prompts like ''run Standard Week next week''.", "Fixed: templates created via the schedule assistant no longer land as invisible orphan rows in the Templates tab."]'::jsonb, '["Navigate to Employees -> Schedule -> Templates tab to build, stage blocks, and generate week templates.", "In the schedule editor assistant, request template creation or ask to apply a saved template to a date range."]'::jsonb, '["Apply migration empsched03."]'::jsonb, NULL, 'action-needed', '2026-08-18T07:20:30.592134+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-219-feat-inventory-add-pos-sales-intake', 14, '2026-08-18'::date, 'Matcha Work', 'POS sales intake and automated inventory movements', 'Introduces POS sales intake into Matcha Work inventory, enabling CSV/PDF/image sales report parsing, item mapping, aggregated sale movements, expected on-hand tracking, and optional Gmail mailbox ingestion.', '["POS sales mappings and automated ''sale'' movement aggregation.", "Deterministic CSV and best-effort PDF/image report parsing with an intake review modal.", "Expected on-hand breakdowns, durable audit variance reports, and unit-cost valuation updates.", "Optional Gmail mailbox polling for automated sales intake with sender routing and draft reviews.", "Controlled via the ''sales_intake'' feature flag."]'::jsonb, '["Matcha Work -> Inventory Hub: Use the new Sales Import modal and Sales Mappings panel to ingest and map POS sales reports."]'::jsonb, '["Apply migration sales01 (not applied to any database yet).", "Enable the ''sales_intake'' feature flag where desired."]'::jsonb, NULL, 'action-needed', '2026-08-18T17:44:35.423174+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-222-book-of-business-refresh-top-metrics', 13, '2026-08-18'::date, 'Broker', 'Refresh Book of Business metrics and KPI filters', 'Refreshed top metrics in the Broker Dashboard, turning KPI cards into interactive filter toggles for the accounts table and streamlining the risk posture view.', '["At-Risk Clients and new Renewal Urgency (<60d) cards now act as clickable filter toggles for the accounts table, complete with a clear-filter banner.", "Simplified the risk posture panel to focus on workers'' comp claim-depth chips (Cumulative trauma, Post-termination, and Open lost-time).", "Removed Total Employees, Risk Index KPI cards, and readiness distribution bars to reduce dashboard clutter."]'::jsonb, '["Broker Dashboard: Click the At-Risk Clients or Renewal Urgency KPI cards to filter the accounts table."]'::jsonb, NULL, NULL, NULL, '2026-08-18T18:55:42.270659+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-221-book-of-business-renewal-countdown', 12, '2026-08-18'::date, 'Broker', 'Book of Business: Renewal countdown column and inline editing', 'Brokers can now view and edit client renewal countdowns directly in the Book of Business table, with automatic derivation from coverage line expiration dates when no manual date is set.', '["Added a Renewal countdown column to the Book of Business dashboard table.", "Color-coded renewal status pills: critical (<60d, red), warning (60-90d, amber), and normal (>90d, muted), with indicators for unconfirmed/derived dates.", "Inline click-to-edit renewal date picker with automatic fallback to earliest coverage line expiry date if cleared.", "Sortable renewal column (soonest renewals first, blanks always last).", "Fixed: dead compliance data reference in client detail overview tab."]'::jsonb, '["Broker: Navigate to Broker Dashboard -> Book of Business table -> Click on any Renewal cell to set or update a renewal date inline."]'::jsonb, '["Apply migration brokerrenew01 (adds renewal_date to broker_company_links)."]'::jsonb, NULL, 'action-needed', '2026-08-18T18:55:42.269343+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-220-trir-headcount-fix-e-mod-copy-update', 11, '2026-08-18'::date, 'Broker', 'TRIR headcount calculation fix, e-mod copy update, and broker tab cleanup', 'Fixes the Workers'' Comp TRIR calculation to use live active-employee headcount, updates Premium Impact Estimate copy to incurred-loss-cost framing, and cleans up client drill-down tabs in the broker portal.', '["Fixed: Workers'' Comp TRIR calculations now use live active-employee headcount instead of stale Stripe billing counts.", "Updated Premium Impact Estimate card copy across Risk Insights and broker Book-of-Business to incurred-loss-cost framing.", "Removed unused Compliance and Activity tabs from the broker client drill-down view."]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, '2026-08-18T18:55:42.265279+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-223-broker-portal-hover-reason-on-at-risk', 10, '2026-08-18'::date, 'Broker', 'Hover breakdown on at-risk badge in Book of Business', 'Brokers can now hover over the at-risk badge in the Book of Business table to view specific contributing risk factors, such as open incident counts and policy compliance rates.', '["Hover tooltip on at-risk badges in the Book of Business client table detailing why a client is flagged (e.g., open incidents, compliance rate).", "Broker portfolio list and company detail endpoints now expose underlying risk signal metrics including open incidents, pending signatures, and active policy count."]'::jsonb, '["Broker Portal -> Book of Business: hover over any ''At risk'' badge in the table to see the risk driver breakdown."]'::jsonb, NULL, NULL, 'new', '2026-08-18T19:46:14.132822+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-226-feat-safety-add-transcribed-safety', 9, '2026-08-18'::date, 'Matcha Compliance', 'Transcribed safety meetings and manager sign-offs', 'New feature-gated safety meeting recording tool with Gemini-powered chunked audio transcription, automated structured summaries, manager review and editing, and typed-name sign-off for immutable records.', '["Record safety meetings directly in the app at /app/safety-meetings with chunked audio upload.", "Automatic transcription and structured summary generation powered by Gemini.", "Manager review and edit workflow with typed-name sign-off producing immutable meeting records.", "Secure private audio retention for meeting recordings."]'::jsonb, '["Navigate to Safety Meetings (/app/safety-meetings) in the sidebar to record a new session, review transcripts, and complete sign-offs."]'::jsonb, '["Apply migration safemeet01 \u2014 not applied to production as of this commit."]'::jsonb, NULL, 'action-needed', '2026-08-20T21:28:18.913766+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-225-feat-broker-streamline-client-detail', 8, '2026-08-18'::date, 'Broker', 'Streamlined broker client detail view', 'Revamped the broker client detail page with dedicated summary cards for headcount, locations, renewal dates, and open exposures, while consolidating tabs into seven focused sections.', '["Replaced the client-detail summary area with summary cards for headcount/locations, renewal details, and open exposures.", "Consolidated 13 client detail tabs down to 7 actionable sections.", "Exposed renewal date and source information directly in the client overview."]'::jsonb, '["Navigate to Client Detail in the broker portal for any linked client."]'::jsonb, NULL, NULL, NULL, '2026-08-20T21:28:18.900461+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-215-feat-schedule-add-editor-assistant-chat', 7, '2026-08-18'::date, 'Employee Scheduling', 'Schedule editor AI assistant chat and proposal cards', 'Introduces an interactive AI assistant panel directly in the schedule editor to help managers stage draft-safe shift creations, edits, and template changes via structured proposal cards.', '["New schedule-editor assistant chat panel with support for conversational shift management.", "Interactive proposal cards to review, clarify, discard, or apply AI-suggested schedule and template changes.", "Draft-safe staging pipeline powered by backend schedule chat and rules services."]'::jsonb, '["Navigate to the Schedule Editor page and open the assistant chat panel from the editor toolbar to prompt schedule modifications or template applications."]'::jsonb, NULL, '["Read-only coverage Q&A is not included yet in this release."]'::jsonb, 'new', '2026-08-18T01:48:19.444004+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-237-gate-shift-transfers-on-bilateral', 6, '2026-08-21'::date, 'Employee Scheduling', 'Bilateral approval for shift swaps and pickups', 'Shift pickup and swap requests now require counterparty confirmation before advancing to manager approval, preventing unconfirmed shift transfers and double-scheduling.', '["Shift swaps and pickups are now staged until the counterparty employee accepts the request.", "Pickup acceptance is blocked if the receiving employee is already scheduled to work that calendar day.", "Shift assignments remain unchanged until final manager approval."]'::jsonb, '["Portal: Employees request, view, and accept shift swaps or pickups under Portal Schedule.", "App: Managers review and give final approval to confirmed shift requests under Employee Schedule."]'::jsonb, '["Apply migration empsched05 (empsched05_bilateral_requests)."]'::jsonb, NULL, 'action-needed', '2026-08-21T22:58:03.774106+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-236-feat-inventory-add-demand-forecasting', 5, '2026-08-21'::date, 'Matcha Work', 'Inventory demand forecasting & Square POS sales sync', 'Adds deterministic inventory demand forecasting with replenishment rules alongside Square POS integration for catalog mapping, finalized sales syncing, and refund normalization.', '["Inventory demand forecasting with immutable advisory snapshots and replenishment rules.", "Square POS integration supporting OAuth, location/catalog mapping, finalized sales sync, and refund normalization.", "AI-assisted scenario drafts powered by Gemini with explicit manager acceptance controls.", "Dedicated Inventory Forecast page and POS connection management panel."]'::jsonb, '["Work -> Inventory -> Forecast: View demand forecasts, replenishment recommendations, and scenario drafts.", "Work -> Inventory -> POS Connection: Connect a Square account and map locations/catalog items."]'::jsonb, '["Apply migrations invforecast01_inventory_forecasting and pos01_square_inventory_sales."]'::jsonb, NULL, 'action-needed', '2026-08-21T22:58:03.773191+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-235-feat-schedule-add-voice-assistant-turns', 4, '2026-08-21'::date, 'Employee Scheduling', 'Voice assistant turns in the schedule editor', 'Added push-to-talk Huume voice assistant support to the schedule editor, enabling managers to dictate schedule changes and execute proposal confirmations or cancellations via voice.', '["Push-to-talk voice dictation in the schedule editor via transient WAV audio uploads.", "Voice transcription routed directly through the draft proposal engine with deterministic confirm and cancel commands.", "Fixed: prevented stale scope updates, recorder races, and duplicate proposal execution across editor, channel, and thread surfaces."]'::jsonb, '["Navigate to the Schedule Editor and use the push-to-talk voice assistant button in the toolbar or chat panel."]'::jsonb, NULL, NULL, 'new', '2026-08-21T22:58:03.772146+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-234-feat-inventory-add-compact-ops-guide', 3, '2026-08-21'::date, 'Matcha Work', 'Compact Inventory Hub layout and Quick Start guide', 'Updated the Inventory Hub with a more compact layout across dashboard views, an inline catalog, section explanation modals, and a first-visit Quick Start wizard.', '["Positioned the full inventory catalog directly beneath summary cards for faster access.", "Compact layouts for the dashboard, item table, order queue, sales mappings, and item detail panels.", "New first-visit Inventory Quick Start wizard guiding audit and receiving actions.", "Section explanation modals explaining inventory metrics, controls, filtered counts, and movement preview limits."]'::jsonb, '["Matcha Work -> Inventory Hub: explore the streamlined catalog layout, Quick Start wizard, and section help modals."]'::jsonb, NULL, NULL, 'new', '2026-08-21T22:58:03.770895+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-233-feat-schedule-surface-compliance', 2, '2026-08-21'::date, 'Employee Scheduling', 'Compliance warnings in employee schedule and EMS reconciliation', 'Schedule and roster views now surface compliance warnings for overdue training and lapsed credentials, reconciling warning events into EMS with deep links and promotion protection.', '["Overdue training and lapsed credential warnings are now surfaced directly in schedule and roster views.", "Schedule compliance warnings automatically reconcile into EMS events with deep links back to schedule views.", "Added automated worker sweeps and schedule write hooks to continuously detect and sync compliance issues."]'::jsonb, '["Open the employee schedule or roster to view inline compliance warning indicators.", "View and manage linked schedule warning events directly in EMS / Events Hub."]'::jsonb, '["Apply migration schedwarn01_schedule_warning_events."]'::jsonb, NULL, 'action-needed', '2026-08-21T22:58:03.768999+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-238-feat-schedule-add-compliance-guidance', 1, '2026-08-21'::date, 'Employee Scheduling', 'Compliance guidance, break rules, and publishing readiness checks for schedules', 'Introduces jurisdiction and industry break-rule resolution, blocks schedule publication until location compliance metadata is complete, and adds individualized break guidance, manager assignment notes, and waiver attestations.', '["Schedule publication readiness: publishing is now blocked until all required location compliance metadata is verified.", "Automated break guidance: evaluates jurisdiction and industry break rules to generate individualized break plans for scheduled shifts.", "Manager assignment notes and waiver attestations persisted directly on employee schedules."]'::jsonb, '["Navigate to Employees -> Schedule to view break rule guidance, resolve readiness blockers, and record assignment notes or attestations before publishing."]'::jsonb, '["Apply migrations empsched06_schedule_guidance, empsched07_schedule_eligibility_cases, and empsched08_location_eligibility_scope."]'::jsonb, NULL, 'action-needed', '2026-08-22T00:45:59.827669+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO admin_updates (id, position, date, category, title, summary, whats_new, how_to_use, setup, notes, tag, created_at) VALUES ('pr-232-feat-ops-add-matcha-ops-landing-and', 0, '2026-08-21'::date, 'Ops', 'Matcha Ops landing page and redesigned inventory hub', 'Introduces a public Matcha Ops landing page with an operational console overview, alongside a redesigned inventory control center featuring stock health, movement flow, reorder intelligence, and an updated order queue.', '["New public Matcha Ops landing page with console motion preview, navigation tab, and footer links.", "Redesigned `/inventory` dashboard with stock health metrics, on-hand value, movement flow, and reorder intelligence.", "Updated item catalog and order queue components within the inventory hub."]'::jsonb, '["Landing: Navigate to the Ops tab from the public marketing header or footer.", "Inventory: Go to `/inventory` to access the updated control center, attention items, and order queue."]'::jsonb, NULL, NULL, 'new', '2026-08-21T22:58:03.759715+00:00'::timestamptz) ON CONFLICT (id) DO NOTHING;
